 async function call(path:string,body?:any,message?:string){setBusy(true);setError('');try{const res=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Demo-Role':role},body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw Error(typeof data.detail==='string'?data.detail:'Please check the required fields and values.');if(data.schema)setS(data);if(message){setToast(message);setTimeout(()=>setToast(''),4500)}return data;}catch(e){setError((e as Error).message);return null}finally{setBusy(false)}}
 useEffect(()=>{call('state')},[]);
