 async function act(path:string,body:any,msg:string,close=true){const d=await call(path,body,msg);if(d&&path.startsWith('demo/reset'))localStorage.removeItem('modelfit-intake');if(d&&close)setModal(null);return d}
 async function startAssessment(ucid:string,mid='M1'){if(await call('assessments',{usecase_id:ucid,model_id:mid},'Assessment workspace opened.')){setSelectedUC(ucid);setPage('Evaluations');setTab('requirements');setModal(null)}}
 function formatDate(t:string){return new Date(t).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'})}
